window.VO = [{"id":"n01","text":"You're the guard, and what you write in this register sends a man to jail.","at":0.24,"t0":0.12,"t1":3.975},{"id":"n02","text":"Flats on this street are being robbed, so ask this delivery man his name.","at":8.45,"t0":4.225,"t1":8.36},{"id":"a01","text":"Ravi, sir.","at":17.12,"t0":8.56,"t1":9.495},{"id":"n03","text":"Write it down, and ask which flat.","at":19.29,"t0":9.645,"t1":11.45},{"id":"b01","text":"Three zero two.","at":23.2,"t0":11.6,"t1":12.795},{"id":"n04","text":"Write that too, and check his parcel.","at":26.29,"t0":13.145,"t1":15.27},{"id":"c01","text":"Here it is, sir.","at":30.84,"t0":15.42,"t1":16.475},{"id":"n05","text":"Does it match your register?","at":33.35,"t0":16.675,"t1":18.085},{"id":"n06","text":"Good catch.","at":38.37,"t0":19.185,"t1":20.055},{"id":"d01","text":"Sorry, sir. I'll call the customer.","at":40.61,"t0":20.305,"t1":22.37},{"id":"n07","text":"So nobody got past you.","at":45.44,"t0":22.72,"t1":24.195},{"id":"n08","text":"Then who robbed flat three zero two?","at":48.79,"t0":24.395,"t1":26.3},{"id":"n09","text":"Police have four men in that jacket, but your register says one came, so point him out.","at":53,"t0":26.5,"t1":31.545},{"id":"n10","text":"He goes to jail, and the other three go home.","at":63.49,"t0":31.745,"t1":34.265},{"id":"n11","text":"Which one? You looked right at him.","at":68.93,"t0":34.465,"t1":36.29},{"id":"n12","text":"You're right. He was at your gate, and so were the other three.","at":76.08,"t0":38.04,"t1":41.095},{"id":"n13","text":"Every time you looked down, one walked in and the next stepped up, and you carried on.","at":83.69,"t0":41.845,"t1":46.14},{"id":"n14","text":"So three of them go home. Four, if you said none.","at":92.88,"t0":46.44,"t1":49.25},{"id":"n15","text":"In a real experiment, a woman who missed a swap like this said she'd just seen a construction worker.","at":99.3,"t0":49.65,"t1":55.035},{"id":"n16","text":"And these four aren't even delivery men. You just saw a jacket.","at":110.67,"t0":55.335,"t1":58.795},{"id":"n17","text":"Your register says Ravi.","at":118.49,"t0":59.245,"t1":60.695},{"id":"n18","text":"So which one was Ravi?","at":121.79,"t0":60.895,"t1":62.225}];
